-- SBC V58.0.0 — Money Intelligence Engine
CREATE TABLE IF NOT EXISTS sbc_money_intelligence_opportunities (id VARCHAR(140) PRIMARY KEY, tenant_id VARCHAR(140) NOT NULL, customer_id VARCHAR(140) NULL, opportunity_type VARCHAR(64) NOT NULL, expected_revenue DECIMAL(14,2) NOT NULL DEFAULT 0, probability_pct DECIMAL(6,2) NOT NULL DEFAULT 0, next_action VARCHAR(80) NULL, status VARCHAR(32) NOT NULL DEFAULT 'OPEN', payload_json LONGTEXT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_mi_tenant_status(tenant_id,status), INDEX idx_mi_expected(tenant_id,expected_revenue)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sbc_ai_budget_ledger (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id VARCHAR(140) NOT NULL, agent VARCHAR(80) NOT NULL, task VARCHAR(120) NOT NULL, estimated_tokens INT NOT NULL DEFAULT 0, estimated_cost DECIMAL(12,6) NOT NULL DEFAULT 0, expected_revenue DECIMAL(14,2) NOT NULL DEFAULT 0, decision VARCHAR(32) NOT NULL, created_at DATETIME NOT NULL, INDEX idx_ai_budget_tenant_date(tenant_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sbc_sales_sequence_telemetry (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id VARCHAR(140) NOT NULL, channel VARCHAR(32) NOT NULL, event_hour TINYINT NULL, responded TINYINT(1) NOT NULL DEFAULT 0, converted TINYINT(1) NOT NULL DEFAULT 0, revenue DECIMAL(14,2) NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, INDEX idx_seq_tenant_channel(tenant_id,channel,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sbc_revenue_anomaly_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, tenant_id VARCHAR(140) NOT NULL, metric_name VARCHAR(80) NOT NULL, metric_value DECIMAL(18,4) NOT NULL, baseline_value DECIMAL(18,4) NOT NULL, change_pct DECIMAL(10,2) NOT NULL, severity VARCHAR(16) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'OPEN', created_at DATETIME NOT NULL, INDEX idx_anomaly_tenant_status(tenant_id,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sbc_worker_runtime_control (control_key VARCHAR(80) PRIMARY KEY, max_workers INT NOT NULL DEFAULT 1, target_workers INT NOT NULL DEFAULT 1, mode VARCHAR(24) NOT NULL DEFAULT 'PROTECT', updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO sbc_worker_runtime_control(control_key,max_workers,target_workers,mode,updated_at) VALUES('global',1,1,'PROTECT',UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE updated_at=updated_at;
